// Package nanogen declares the inputs of anchor's code generation that nanostack
// gen cannot discover. Run from apps/anchor: go tool nanostack gen
//
// API stays nil: the server and the clients are generated by oapi-codegen
// from generate_anchor.sh and the Makefile, so the HTTP boundary does not
// change.
package nanogen

import "github.com/nanostack-dev/nanostack-framework/core/nano/project"

// Project is read from source by nanostack gen; nothing calls it.
var Project = project.Project{ //nolint:gochecknoglobals // a declaration nanostack gen reads, like nano.Manifest
	Postgres: &project.Postgres{
		Name: "anchor",
		// TimescaleDB, not plain Postgres: the usage migration creates a
		// hypertable. Keep this image equal to docker-compose.yml,
		// cmd/it/shared/test_setup.go and the generatedCode check in
		// .dagger/modules/anchor/main.dang.
		Image:  "timescale/timescaledb:2.23.0-pg18",
		Scopes: []string{"platform_tenant_id", "product_id", "organization_id"},
	},
	Env: ".env.example",
}
